window.docContents[20].resolve({"/2___-Basic-notions-of-representation-theory/2___11___-Tensor-products/Bimodules-and-tensor-products___-associativity-and-Hom-tensor-adjunction/#Chapter2___Problem2___11___6___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.11. Tensor products\u0009Bimodules and tensor products: associativity and Hom-tensor adjunction\u0009Bimodules and tensor products: associativity and Hom-tensor adjunction","header":"Formalization","id":"/2___-Basic-notions-of-representation-theory/2___11___-Tensor-products/Bimodules-and-tensor-products___-associativity-and-Hom-tensor-adjunction/#Chapter2___Problem2___11___6___formalization"},"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Irreducible-and-indecomposable-quiver-representations/#Chapter2___Discussion_quiver_irreducible_indecomposable___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.8. Quivers\u0009Irreducible and indecomposable quiver representations\u0009Irreducible and indecomposable quiver representations","header":"Formalization","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Irreducible-and-indecomposable-quiver-representations/#Chapter2___Discussion_quiver_irreducible_indecomposable___formalization"},"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Canonical-decomposition-of-semisimple-representations-via-Schur___s-lemma/#Chapter3___Remark3___1___3___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.1. Subrepresentations in semisimple representations\u0009Canonical decomposition of semisimple representations via Schur's lemma\u0009Canonical decomposition of semisimple representations via Schur's lemma","header":"Formalization","id":"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Canonical-decomposition-of-semisimple-representations-via-Schur___s-lemma/#Chapter3___Remark3___1___3___formalization"},"/3___-General-results-of-representation-theory/3___2___-The-density-theorem/Any-linear-map-on-linearly-independent-vectors-is-realized-by-an-algebra-element/#Chapter3___Corollary3___2___1___formalization":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.2. The density theorem\u0009Any linear map on linearly independent vectors is realized by an algebra element\u0009Any linear map on linearly independent vectors is realized by an algebra element","header":"Formalization","id":"/3___-General-results-of-representation-theory/3___2___-The-density-theorem/Any-linear-map-on-linearly-independent-vectors-is-realized-by-an-algebra-element/#Chapter3___Corollary3___2___1___formalization"},"/5___-Representations-of-finite-groups___-Further-results/5___18___-Schur-Weyl-duality-for-______mathfrak___gl____LPAR_V_RPAR____/Double-Centralizer-Theorem/#Chapter5___Theorem5___18___1":{"contents":"Theorem 5.18.1. Let A, B be two subalgebras of the algebra \\operatorname{End} E of endomorphisms of a finite dimensional vector space E, such that A is semisimple and B = \\operatorname{End}_A E. Then:\n\n(i) A = \\operatorname{End}_B E (i.e., the centralizer of the centralizer of A is A).\n\n(ii) B is semisimple.\n\n(iii) As a representation of A \\otimes B, E decomposes as\n\nE = \\bigoplus_{i \\in I} V_i \\otimes W_i,\n\nwhere V_i are all the irreducible representations of A and W_i are all the irreducible representations of B. In particular, we have a natural bijection between irreducible representations of A and B.\n\nProof. Since A is semisimple, we have a natural decomposition E = \\bigoplus_{i \\in I} V_i \\otimes W_i, where W_i := \\operatorname{Hom}_A(V_i, E) and A = \\bigoplus_i \\operatorname{End} V_i. Note that W_i \\neq 0, since the action of A on E is faithful. Therefore, by\nSchur's lemma, B = \\operatorname{End}_A(E) is naturally identified with \\bigoplus_i \\operatorname{End}(W_i). This implies all the statements of the theorem. \\square\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.18. Schur-Weyl duality for $\\mathfrak{gl}(V)$\u0009Double Centralizer Theorem","header":"Double Centralizer Theorem","id":"/5___-Representations-of-finite-groups___-Further-results/5___18___-Schur-Weyl-duality-for-______mathfrak___gl____LPAR_V_RPAR____/Double-Centralizer-Theorem/#Chapter5___Theorem5___18___1"},"/5___-Representations-of-finite-groups___-Further-results/5___22___-The-characters-of-___L____lambda___/Irreducible-representations-of-GL_LPAR_V_RPAR_-labeled-by-Young-diagrams/#Chapter5___Discussion_after_Theorem5___22___1":{"contents":"This shows that irreducible representations of GL(V) which occur in V^{\\otimes n} for some n are labeled by Young diagrams with any number of squares but at most N = \\dim V rows.\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.22. The characters of $L_\\lambda$\u0009Irreducible representations of GL(V) labeled by Young diagrams","header":"Irreducible representations of GL(V) labeled by Young diagrams","id":"/5___-Representations-of-finite-groups___-Further-results/5___22___-The-characters-of-___L____lambda___/Irreducible-representations-of-GL_LPAR_V_RPAR_-labeled-by-Young-diagrams/#Chapter5___Discussion_after_Theorem5___22___1"},"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Corollary-6___8___2___-Dimension-vector-of-indecomposable-is-a-positive-root/#Chapter6___Corollary6___8___2":{"contents":"Corollary 6.8.2. Let Q be a quiver, and let V be any indecomposable representation. Then d(V) is a positive root.\n\nProof. By the proof of Theorem 6.8.1\n\ns_{i_1} \\ldots s_{i_m} (d(V)) = \\alpha_p.\n\nSince the s_i preserve B, we get\n\nB(d(V), d(V)) = B(\\alpha_p, \\alpha_p) = 2.\n\n\\square\n\n\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.8. Proof of Gabriel's theorem\u0009Corollary 6.8.2: Dimension vector of indecomposable is a positive root","header":"Corollary 6.8.2: Dimension vector of indecomposable is a positive root","id":"/6___-Quiver-representations/6___8___-Proof-of-Gabriel___s-theorem/Corollary-6___8___2___-Dimension-vector-of-indecomposable-is-a-positive-root/#Chapter6___Corollary6___8___2"},"/Frontmatter/Table-of-Contents/#Introduction-to-Representation-Theory--Frontmatter--Table-of-Contents":{"contents":"\n\n","context":"Introduction to Representation Theory\u0009Frontmatter","header":"Table of Contents","id":"/Frontmatter/Table-of-Contents/#Introduction-to-Representation-Theory--Frontmatter--Table-of-Contents"}});